    // out_index = ((n*C + c)*OH + ph)*OW + pw
    cvt.u64.u32     %rd18, %r20;               // n
    cvt.u64.u32     %rd19, %r1;                // C
    mul.lo.u64      %rd20, %rd18, %rd19;       // n*C
    cvt.u64.u32     %rd21, %r19;               // c
    add.u64         %rd22, %rd20, %rd21;       // n*C + c
    cvt.u64.u32     %rd23, %r4;                // OH
    mul.lo.u64      %rd24, %rd22, %rd23;       // *OH
    cvt.u64.u32     %rd25, %r17;               // ph
    add.u64         %rd26, %rd24, %rd25;       // + ph
    cvt.u64.u32     %rd27, %r5;                // OW
    mul.lo.u64      %rd28, %rd26, %rd27;       // *OW
    cvt.u64.u32     %rd29, %r15;               // pw
    add.u64         %rd30, %rd28, %rd29;       // final out index

    // byte offset = index * 2
    shl.b64         %rd31, %rd30, 1;

    // global address = out base + offset
    cvta.to.global.u64 %rd32, %rd1;            // out base
    add.u64         %rd33, %rd32, %rd31;

    // write max value
    st.global.f16   [%rd33], %h0;

$L_EXIT:
    ret;
